from pathlib import Path
import json
r=Path(__file__).resolve().parent.parent;m=json.loads((r/'manifest.json').read_text());(r/'player.js').write_text('const specs='+json.dumps(m['clips'],separators=(',',':'))+';\n'+r'''const $=id=>document.getElementById(id),ctx=$('stage').getContext('2d'),C=192, images={};
let mode='rest',playing=true,clock=0,last=0,ready=false,loadToken=0,timeline=[],total=0;
const desc={rest:'48 cleaned source poses: stand, sit, become drowsy, doze while seated, wake, and stand.',floor:'48 extracted concept poses: standing, seated, lowering to a curled sleep, waking and rising. Lower-resolution prototype with variable pose scale.',speech:'32 aligned expression poses; experimental source gallery only, not talking or lip synchronization.'};
function phase(name,i){if(name==='speech')return 'Expression study';if(name==='rest')return i<8?'Sit down':i<16?'Drowsy':i<25?'Seated sleep':i<34?'Wake up':'Stand up';return i<8?'Sit down':i<16?'Drowsy and lower':i<24?'Curled sleep':i<34?'Wake up':'Stand up'}
function build(){let q=specs[mode],seq=q.sequence;timeline=[];total=0;for(let j=0;j<seq.length;j++){let i=seq[j],label=phase(mode,i);if(mode==='floor'&&j>=33)label='Stand up';if(j===0)label='Standing';if(j===seq.length-1&&mode!=='speech')label='Standing · recovered';let hold=j===0||j===seq.length-1?.55:mode==='speech'?.16:(label.includes('sleep')?.32:.16);let smooth=$('smooth').checked&&mode!=='speech'&&j<seq.length-1;timeline.push({start:total,end:total+hold*(smooth?.5:1),index:i,atlas:q.atlas,label});if(smooth)timeline.push({start:total+hold*.5,end:total+hold,index:j,atlas:q.interpolatedAtlas,label});total+=hold}return total}
function load(name){if(images[name])return Promise.resolve(images[name]);return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>{images[name]=im;resolve(im)};im.onerror=()=>reject(Error('Unable to load '+name));im.src=name})}
function show(t){if(!ready)return;clock=Math.max(0,Math.min(total,t));let f=timeline.find(x=>clock<x.end)||timeline.at(-1),im=images[f.atlas];ctx.clearRect(0,0,384,384);ctx.save();ctx.scale(2,2);ctx.drawImage(im,f.index%8*C,Math.floor(f.index/8)*C,C,C,0,0,C,C);ctx.restore();$('seek').value=String(Math.round(clock/total*1000));$('status').textContent=`${f.label} · ${clock.toFixed(2)} / ${total.toFixed(2)} s · ${f.atlas.includes('-mid')?'Interpolated':'Source'} frame ${f.index+1}`;return f}
function setPlay(v){playing=v;$('play').textContent=v?'Pause':'Play'}
async function choose(name){let token=++loadToken;mode=name;ready=false;setPlay(false);$('desc').textContent=desc[name];$('status').textContent='Loading…';document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===name));$('smooth').disabled=name==='speech';$('sheet').src=specs[name].atlas;try{await Promise.all([load(specs[name].atlas),...(specs[name].interpolatedAtlas?[load(specs[name].interpolatedAtlas)]:[])]);if(token!==loadToken)return;build();ready=true;show(0);setPlay(true)}catch(e){if(token===loadToken)$('status').textContent=e.message}}
function loop(now){let dt=last?Math.min(.12,(now-last)/1000):0;last=now;if(ready&&playing){let t=clock+dt*Number($('speed').value);if(t>=total){if($('loop').checked)t%=total;else{t=total;setPlay(false)}}show(t)}requestAnimationFrame(loop)}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>choose(b.dataset.mode));$('play').onclick=()=>{if(!ready)return;if(!playing&&clock>=total)show(0);setPlay(!playing)};$('restart').onclick=()=>{show(0);setPlay(true)};$('seek').oninput=()=>{setPlay(false);show(total*Number($('seek').value)/1000)};$('smooth').onchange=()=>{if(!ready)return;const p=clock/total;build();show(p*total)};function step(n){if(!ready)return;setPlay(false);let i=timeline.findIndex(x=>clock<x.end);if(i<0)i=timeline.length-1;let j=Math.min(timeline.length-1,Math.max(0,i+n));show(timeline[j].start+0.00001)}$('prev').onclick=()=>step(-1);$('next').onclick=()=>step(1);window.inspectSprite=(t)=>{setPlay(false);return show(t)};window.spriteState=()=>({mode,ready,total,clock,timeline,playing});window.chooseSprite=choose;choose('rest');requestAnimationFrame(loop);
''')
